    "comment": "Ka aku baru beli ip 17 base dan baru 3 mimgguan pake. Aku ngerasa ada yg gak normal sama ip ku. Dosaat orang2 bilang batrenya awet dan gak panas, kok ak gak ngerasa gitu ya di ip ku. Kayak contoh nya, cell data off, wifi on aku ngetik di WA 3-5 menit aja batrenya berkurang 1%, dengerin lagu di spotify 2 jam berkurang 8%, scroll shopi sambil spotify terus buka astro bentar sama tiktok rotal 1,5 jam berkurang 20%. Nonton live sopi 40 menitan berkurang 7% , scroll sopi tanpa live 7 menit berkurang 2%. Capcut 36 menit berkurang 3%, screen locked 3jam 11 mnt berkurqng 2%, Terus juga ak ngerasa kayak si persentase batrenya itu agak telat berkurangnya kyk agak ketinggalan dari aslinya, terutama kalo pas layar di kunci, pas dibuka di langsung kurang 1 %. Kadang jga suka nambah sendiri persentazenya 1% pdhl gak di charge. Dqn aku ngerasw Cepet anget juga pdhl cuma dipake nonton live toktok atau sopi 30 menitan. Jujur janggal, ak jadi overthinking ka, apa unit ku defect. Gimana yaaa masa udah harus di service. Oh ya padahal aku juga udah offim settingan yg gak terlalu penting atau bikin boros batre. Kayak background app refresh, AOD, Lokasi, haptic and lock sound, dll kyk yg bnym di share itu settingan tips biar batre lebih hemat. Tetep aj gak ngaruh banyak sepertinya. Asli worry dan bingung bnggt.",
